"""Add candidate532 operational notes before the package content is frozen."""
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2]
def prepend(relative,text):
    p=ROOT/relative;b=p.read_bytes()
    if b'473' in b.split(b'\n',4)[2]:raise SystemExit('532 manual notes already written')
    first,rest=b.split(b'\n',1);p.write_bytes(first+b'\n\r\n'+text.replace('\n','\r\n').encode('utf-8')+b'\r\n'+rest)
def main():
    prepend('docs/MANUAL-PAQUETE-WINDOWS-S1.md','**Candidata interna532 · grupo473–532.** Incluye editor tipado de configuración privada, XLSX tabular y avisos descriptivos del inventario. Se conservan SQL001–009 y las dependencias fijadas. Los perfiles337/397 siguen verificándose para recuperación; usar siempre el hash externo del ZIP elegido. Sigue pendiente la adopción final y el cierre de servicio/identidad/PKI/Windows limpio/licencias; no es un instalador final certificado.\n\nEn el inventario del cliente abre Mis plantillas privadas y pulsa Crear configuración nueva. Elige una semilla y Usar como borrador, modifica los campos tipados, Revisar configuración, confirma las etiquetas reutilizables y pulsa Guardar plantilla nueva. Se crea otra identidad; la original y sus equipos no cambian. Tras un envío incierto consulta su estado antes de repetir. Después de recargar, la definición no guardada ya no está en memoria: consulta o cancela para confirmar el fence y rehace el borrador; no hay reintento durable del blueprint. El administrador recuperado tiene su biblioteca privada propia; la del usuario original permanece ligada a ese usuario.')
    prepend('docs/CONSTRUIR-PAQUETE-WINDOWS-S1.md','**Actualización473–532.** El productor y lector aceptan también el manifiesto cerrado CANDIDATA532-FINAL02 (aplicación y GUI532, esquema9). No admitir un hash arbitrario como nueva versión. El perfil532 provisional01 fue sustituido antes de ensayos/selección; se conserva como evidencia de desarrollo, sin perfil de instalación aceptado. Construir dos ZIP en salidas nuevas después de congelar aplicación,25operadores y4manuales; comparar sus bytes y manifiestos. Los perfiles337/397 y ZIP anteriores se conservan. Los nuevos operadores QA de desarrollo no forman parte de los25operadores de instalación.')
    prepend('docs/OPERAR-DESPLIEGUE-PRIVADO-WINDOWS-S1.md','**Aplicación532.** La operación Windows conserva el mismo recibo y protocolo. El editor privado guarda configuraciones nuevas con una revisión personal y confirmación de commit; no cambia la revisión del inventario. Los avisos descriptivos se consultan con permisos actuales y no aplican automáticamente la vista. Ante petición incierta conservar el contexto y usar Consultar/Cancelar antes de reconstruir un borrador. No confundir este flujo con la actualización del QA de desarrollo ni cambiar manualmente las rutas o digests del recibo.')
    prepend('docs/RECUPERACION-DESPLIEGUE-WINDOWS-S1.md','**Compatibilidad532.** Backup/restore incluyen las mismas tablasSQL9: las configuraciones privadas nuevas, sus bytes canónicos y recibos pertenecen al propietario original y se recuperan con él. Un administrador nuevo de recuperación no hereda su biblioteca personal. Las sesiones copiadas se revocan; volver a autenticar con cuentas válidas. La recuperación sigue creando ROOT/clúster/base/roles/secretos/TLS nuevos y nunca sobrescribe el origen. La restauración de la aplicación no certifica recuperación integral del host, servicio, PKI productiva o retención.')
    print('Four operational manuals updated before package freeze.')
if __name__=='__main__':main()
